var LLM_CONFIG = {
  TEMPERATURE: 0.7,
  // Balance between creativity and consistency
  MAX_TOKENS: {
    REPO_SUMMARY: 800,
    // ~600 words for detailed project description
    USER_INTRO: 600
    // ~450 words for professional introduction
  },
  TIMEOUT: parseInt(process.env.OPENAI_TIMEOUT || "60000", 10),
  MAX_RETRIES: parseInt(process.env.OPENAI_MAX_RETRIES || "2", 10),
  DEFAULT_MODEL: process.env.OPENAI_API_MODEL || "gpt-4o",
  README_MAX_LENGTH: 2e3
  // Maximum README characters to send to LLM
};
var openaiClient = null;
function getOpenAIClient(apiKey) {
  if (!openaiClient) {
    openaiClient = new openai_default({
      apiKey,
      timeout: LLM_CONFIG.TIMEOUT,
      maxRetries: LLM_CONFIG.MAX_RETRIES,
      ...process.env.OPENAI_API_BASE_URL && { baseURL: process.env.OPENAI_API_BASE_URL }
    });
    console.log("\u2713 OpenAI client initialized");
  }
  return openaiClient;
}
async function generateWithOpenAI(prompt, userContent, apiKey, options) {
  const openai = options ? new openai_default({
    apiKey,
    baseURL: options.baseURL,
    timeout: LLM_CONFIG.TIMEOUT,
    maxRetries: LLM_CONFIG.MAX_RETRIES
  }) : getOpenAIClient(apiKey);
  const response = await openai.chat.completions.create({
    model: options?.model || LLM_CONFIG.DEFAULT_MODEL,
    messages: [
      {
        role: "system",
        content: prompt
      },
      {
        role: "user",
        content: userContent
      }
    ],
    response_format: { type: "json_object" },
    temperature: LLM_CONFIG.TEMPERATURE,
    max_tokens: LLM_CONFIG.MAX_TOKENS.REPO_SUMMARY
  });
  if (!response?.choices || !Array.isArray(response.choices) || response.choices.length === 0) {
    throw new Error("Invalid response structure from LLM API");
  }
  const choice = response.choices[0];
  if (!choice?.message) {
    throw new Error("Invalid choice structure in LLM response");
  }
  if (choice.finish_reason === "length" || choice.finish_reason === "content_filter" || choice.message.refusal) {
    throw new Error("Summary response was incomplete or refused");
  }
  const content = choice.message.content;
  if (!content) {
    throw new Error("No content in LLM response message");
  }
  try {
    const parsed = JSON.parse(content);
    if (typeof parsed.summary !== "string" || !parsed.summary.trim()) {
      throw new Error("Summary response must contain nonempty summary text");
    }
    return { summary: parsed.summary.trim() };
  } catch (parseError) {
    throw new Error(
      `Failed to parse JSON response: ${parseError instanceof Error ? parseError.message : String(parseError)}`
    );
  }
}

// server/lib/organization-source.ts
function createOrganizationSource(token) {
  const octokit = new Octokit2({
    auth: token,
    baseUrl: process.env.GITHUB_API_URL || "https://api.github.com",
    request: { timeout: 3e4 }
  });
  return {
    async discover(config) {
      try {
        const { data } = await octokit.orgs.get({ org: config.organization });
        const organization = {
          login: data.login,
          name: data.name || null,
          description: data.description || null,
          avatarUrl: data.avatar_url || null,
          url: data.html_url
        };
        const repositories = await getOrganizationRepositories(octokit, organization, config);
        return { organization, repositories };
      } catch {
        throw new Error(`Could not fetch all public repositories for ${config.organization}`);
      }
    },
    async readme(owner, repo) {
      try {
        const { data } = await octokit.repos.getReadme({ owner, repo });
        return Buffer.from(data.content, "base64").toString("utf8");
      } catch (error2) {
        if (error2.status === 404) return "";
        throw new Error(`Could not fetch README for ${owner}/${repo}`);
      }
    },
    async structure(owner, repo) {
      try {
        const structure = await analyzeProjectStructure(token, owner, repo, {
          strict: true,
          octokit
        });
        structure.rootFiles.sort();
        structure.directories.sort();
        structure.packageFiles.sort((a2, b2) => a2.name.localeCompare(b2.name));
        structure.configFiles.sort((a2, b2) => a2.name.localeCompare(b2.name));
        structure.sourceFiles.sort((a2, b2) => a2.name.localeCompare(b2.name));
        structure.techStack.sort();
        return generateProjectSummary(structure);
      } catch (error2) {
        if (error2.status === 404) return "No project files available.";
        throw new Error(`Could not analyze project structure for ${owner}/${repo}`);
      }
    }
  };
}

